"""Writes srs-fixtures.json from lxsrs_v2's own protocol.py and models.py (ADR 0158: the Node port is checked against
bytes the Python produced). Run once by hand, from crc-desktop/:

    python3 -I tests/fixtures/srs/make-fixtures.py

It needs only the standard library. The tests read the committed JSON and never run Python.
"""
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[2] / "python-pkg"))

from lxsrs_v2.models import Client, MessageType, Modulation, PlayerRadioInfo, make_radio, default_radio_info  # noqa: E402
from lxsrs_v2.protocol import VoicePacket, encode_network_message  # noqa: E402

GUID_A = "0123456789abcdefghijkl"
GUID_B = "ZYXWVUTSRQPONMLKJIHGFE"

packets = []
for name, pkt in [
    ("one-frequency", VoicePacket(bytes(range(40)), [251_000_000.0], [0], [0], 1, 1, 0, GUID_A.encode(), GUID_A.encode())),
    ("group-three-frequencies", VoicePacket(bytes([0xFC, 0xFF, 0xFE]) * 30, [251_000_000.0, 122_100_000.0, 243_000_000.0],
                                            [0, 0, 0], [0, 0, 0], 7, 123456789012, 0, GUID_A.encode(), GUID_A.encode())),
    ("relayed-fm-encrypted", VoicePacket(b"\x01\x02", [30_000_000.0], [1], [5], 4294967295, 2**53 - 1, 1,
                                         GUID_B.encode(), GUID_A.encode())),
    ("no-audio", VoicePacket(b"", [305_500_000.0], [0], [0], 1, 2, 0, GUID_A.encode(), GUID_A.encode())),
]:
    packets.append({
        "name": name,
        "fields": {
            "audioHex": pkt.audio_part1.hex(),
            "frequencies": pkt.frequencies,
            "modulations": pkt.modulations,
            "encryptions": pkt.encryptions,
            "unitId": pkt.unit_id,
            "packetNumber": pkt.packet_number,
            "retransmissionCount": pkt.retransmission_count,
            "transmissionGuid": pkt.transmission_guid.decode(),
            "clientGuid": pkt.client_guid.decode(),
        },
        "hex": pkt.encode().hex(),
    })

radios = default_radio_info([251_000_000.0, 122_100_000.0]).radios
radios[2] = make_radio(243_000_000.0, name="Guard UHF!")
messages = []
for name, msg_type, client in [
    ("sync-no-radios", MessageType.SYNC, Client(ClientGuid=GUID_A, Name="CRC", Coalition=2)),
    ("radio-update", MessageType.RADIO_UPDATE, Client(
        ClientGuid=GUID_A, Name="", Coalition=0,
        RadioInfo=PlayerRadioInfo(radios=radios, unit="CRC", unitId=1, selected=1))),
    ("ping", MessageType.PING, Client(ClientGuid=GUID_A, Name="CRC")),
]:
    messages.append({"name": name, "msgType": int(msg_type),
                     "line": encode_network_message(msg_type, client, "2.3.3.3").decode()})

out = {"_comment": "Generated by make-fixtures.py from lxsrs_v2 protocol.py/models.py. Do not edit by hand.",
       "guidA": GUID_A, "guidB": GUID_B, "packets": packets, "messages": messages}
(HERE / "srs-fixtures.json").write_text(json.dumps(out, indent=2) + "\n")
print("wrote", HERE / "srs-fixtures.json")
